DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT108-S3-Q16$batch09$ AND q.stimulus=$batch09$To act responsibly in one's professional capacity, one must act on the basis of information that one has made a reasonable effort to make sure is accurate and complete.$batch09$ AND q.prompt=$batch09$Which one of the following judgments most closely conforms to the principle cited above?$batch09$ AND q.correct_choice=$batch09$C$batch09$) THEN RAISE EXCEPTION 'Question changed: PT108-S3-Q16'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch09$b0c57730-1537-4a9c-b918-8e947c7fc1f2$batch09$) <> 2 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch09$b0c57730-1537-4a9c-b918-8e947c7fc1f2$batch09$) <> 4 THEN RAISE EXCEPTION 'Explanation changed: PT108-S3-Q16'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$C$batch09$, $batch09$The conclusion says Toril did not act responsibly, so this choice is worth reading. Does the evidence say Toril didn't make a reasonable effort to get accurate and complete information? Yes: Toril invested the company's money without investigating the risks. Investing company money is a professional act, so the principle applies. The large return doesn't matter. The rule judges the effort made before acting, not how things turned out.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT108-S3-Q16$batch09$ AND e.id=$batch09$b0c57730-1537-4a9c-b918-8e947c7fc1f2$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
